-- Pending invitation security migration. Review before applying.
alter table public.organization_invitations add column if not exists token_hash text unique;
create index if not exists organization_invitations_token_hash_idx on public.organization_invitations(token_hash);
create or replace function public.accept_organization_invitation(p_token_hash text) returns uuid language plpgsql security definer set search_path=public, auth as $$ declare v public.organization_invitations; v_email text; begin if auth.uid() is null then raise exception 'not authenticated'; end if; select email into v_email from auth.users where id=auth.uid(); select * into v from public.organization_invitations where token_hash=p_token_hash and accepted_at is null and expires_at>now() and lower(email)=lower(v_email) for update; if v.id is null then raise exception 'invalid or expired invitation'; end if; insert into public.organization_members(organization_id,user_id,role) values(v.organization_id,auth.uid(),v.role) on conflict do nothing; update public.organization_invitations set accepted_at=now() where id=v.id and accepted_at is null; return v.organization_id; end; $$;
revoke all on function public.accept_organization_invitation(text) from public;grant execute on function public.accept_organization_invitation(text) to authenticated;
